-- ============================================================
-- SPRINT 6.1 — OFFICIAL ROUTINE LIBRARY (60 complete routines)
-- Each routine is a complete form with fields, rules, validation.
-- Author: HomeFlow (system)
-- ============================================================

-- ============================================================
-- Helper: insert routine if not exists
-- ============================================================
CREATE OR REPLACE FUNCTION public.seed_routine(
  _category text,
  _title text,
  _description text,
  _tags text[],
  _planner_view text,
  _schema jsonb
) RETURNS void LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.templates WHERE is_system = true AND title = _title AND category = _category) THEN
    INSERT INTO public.templates (category, title, description, tags, is_system, is_public, planner_view, schema, content, language)
    VALUES (_category, _title, _description, _tags, true, true, _planner_view, _schema, '{}'::jsonb, 'pt-BR');
  END IF;
END; $$;

